// ❌ OLD: instanceof chains have no exhaustiveness guarantee. If a
// new Shape subtype is added, this method silently falls through to
// the default (or returns a wrong value) — the compiler cannot tell
// you that you missed a case.
public class AreaLegacy {
  public double area(Shape s) {
    // ❌ OLD: manual dispatch, unverifiable
    if (s instanceof Circle c) return Math.PI * c.r() * c.r();
    if (s instanceof Square sq) return sq.side() * sq.side();
    // ❌ OLD: adding a Triangle silently reaches this fallback
    throw new IllegalArgumentException("unknown shape");
  }
}

