// ✅ NEW: sealed hierarchy + exhaustive switch. The compiler checks
// that every permitted subtype is covered — no default needed, and
// adding a new permitted type breaks the build until you handle it.
public sealed interface Shape permits Circle, Square, Triangle {}

// ✅ NEW: records as data carriers
public record Circle(double r) implements Shape {}
public record Square(double side) implements Shape {}
public record Triangle(double base, double height) implements Shape {}

public class AreaModern {
  public double area(Shape s) {
    // ✅ NEW: exhaustive — the compiler proves completeness
    return switch (s) {
      case Circle c -> Math.PI * c.r() * c.r();
      case Square sq -> sq.side() * sq.side();
      case Triangle t -> 0.5 * t.base() * t.height();
    }; // ✅ NEW: no default; adding a new Shape subtype = compile error
  }
}

